        ps.clone()
    };
    if strategy == "window" {
        chosen.reverse()
    }
    let mut accepted = vec![];
    for p in chosen {
        let text = if strategy == "summary" {
            facts(&p)
        } else {
            p.text.clone()
        };
        let msg = Message {
